        List<TransferView> transfers,
        List<LoanView> loans,
        List<InspectionView> inspections) {
}

package com.example.starter.evidence;

/**
 * 交接记录状态。
 * PENDING 待接收；ACCEPTED 已接受；CANCELLED 已取消。决定后不可再变。
 */
public enum TransferStatus {
    PENDING,
    ACCEPTED,
    CANCELLED
}

package com.example.starter.evidence;

/**
 * 借出记录状态。
 * ACTIVE 未归还（每件证物至多一笔）；RETURNED 已归还（不可再变，历史不可覆盖）。
 */
public enum LoanStatus {
    ACTIVE,
    RETURNED
}

package com.example.starter.evidence;

import java.time.LocalDateTime;

/**
 * 封条核验记录实体，对应 seal_inspection 表。记录只追加、不可变。
 *
 * @param id          主键
 * @param evidenceKey 关联证物业务键
 * @param inspectorId 提交核验的当前保管人
 * @param passed      核验结果：true 通过 / false 失败（证物进入 SEAL_BROKEN）
 * @param note        核验备注；null 表示未填写
 * @param createdAt   核验提交时间（Asia/Shanghai）
 */
public record SealInspection(
        Long id,
        String evidenceKey,
        String inspectorId,
        boolean passed,
        String note,
        LocalDateTime createdAt) {
}

